interface SymbolConstructor { readonly iterator: unique symbol; }
declare const Symbol: SymbolConstructor;
interface Iterator<T> { next(): { value: T; done: boolean }; }
interface Iterable<T> { [Symbol.iterator](): Iterator<T>; }
interface Array<T> extends Iterable<T> { [key: number]: T; length: number; }
interface ReadonlyArray<T> extends Iterable<T> { readonly [key: number]: T; readonly length: number; }
interface Set<T> extends Iterable<T> {}
interface Promise<T> { then(callback: (value: T) => unknown): unknown; }
interface PromiseConstructor { all(values: unknown): Promise<unknown>; }
declare const Promise: PromiseConstructor;
